import java.util.*;
import java.math.*;

public class Main {
    static class ModInt {
        long value;
        int mod;

        public ModInt(long value, int mod) {
            this.mod = mod;
            this.value = ((value % mod) + mod) % mod;
        }

        public ModInt add(ModInt other) {
            return new ModInt(this.value + other.value, this.mod);
        }

        public ModInt subtract(ModInt other) {
            return new ModInt(this.value - other.value, this.mod);
        }

        public ModInt multiply(ModInt other) {
            return new ModInt(this.value * other.value, this.mod);
        }

        public long val() {
            return this.value;
        }
    }

    static class Pair {
        ModInt first;
        ModInt second;

        public Pair(ModInt first, ModInt second) {
            this.first = first;
            this.second = second;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        // Compute binomial coefficients C
        ModInt[][] C = new ModInt[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                C[i][j] = new ModInt(0, mod);
            }
        }
        C[0][0] = new ModInt(1, mod);
        for (int i = 1; i <= n; i++) {
            C[i][0] = new ModInt(1, mod);
            for (int j = 1; j <= i; j++) {
                C[i][j] = C[i - 1][j - 1].add(C[i - 1][j]);
            }
        }

        // Compute g array
        ModInt[] g = new ModInt[n + 1];
        for (int i = 0; i <= n; i++) {
            long val = (long) i * (i + 1) / 2;
            g[i] = new ModInt(val, mod);
        }

        // Compute f array
        Pair[] f = new Pair[n + 1];
        f[0] = new Pair(new ModInt(1, mod), new ModInt(0, mod));
        for (int i = 1; i <= n; i++) {
            ModInt f_i_first = new ModInt(0, mod);
            ModInt f_i_second = new ModInt(0, mod);
            for (int j = 0; j < i; j++) {
                ModInt z = f[j].first.multiply(f[i - 1 - j].first).multiply(C[i - 1][j]);
                f_i_first = f_i_first.add(z.multiply(new ModInt(i + 1, mod)));
                ModInt sum_g = g[j].add(g[i - 1 - j]);
                f_i_second = f_i_second.add(z.multiply(sum_g));
                ModInt term1 = f[i - 1 - j].first.multiply(f[j].second);
                ModInt term2 = f[j].first.multiply(f[i - 1 - j].second);
                ModInt sum_terms = term1.add(term2);
                f_i_second = f_i_second.add(sum_terms.multiply(C[i - 1][j]).multiply(new ModInt(i + 1, mod)));
            }
            f[i] = new Pair(f_i_first, f_i_second);
        }

        // Initialize DP array
        Pair[][] dp = new Pair[n + 2][m + 1];
        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Pair(new ModInt(0, mod), new ModInt(0, mod));
            }
        }
        dp[0][0] = new Pair(new ModInt(1, mod), new ModInt(0, mod));

        for (int l = 0; l <= n; l++) {
            for (int r = l + 1; r <= n + 1; r++) {
                int di = r - l - 1;
                for (int i = 0; i + di <= m; i++) {
                    Pair prev = dp[l][i];
                    Pair f_di = f[di];
                    ModInt z = prev.first.multiply(f_di.first);
                    // Update dp[r][i + di]
                    Pair current = dp[r][i + di];
                    current.first = current.first.add(z.multiply(C[i + di][di]));
                    ModInt sum_second = prev.second.multiply(f_di.first).add(prev.first.multiply(f_di.second));
                    current.second = current.second.add(sum_second.multiply(C[i + di][di]));
                    dp[r][i + di] = current;
                }
            }
        }

        System.out.println(dp[n + 1][m].second.val());
        sc.close();
    }
}

